#include <bits/stdc++.h>
using namespace std;
using lint = long long;
const lint MOD = 1000000007;

lint mod_pow(lint b, lint e) {
    lint res = 1;
    while (e) {
        if (e & 1) res = res * b % MOD;
        b = b * b % MOD;
        e >>= 1;
    }
    return res;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    vector<vector<int>> p(6, vector<int>(6));
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j) {
            int x;
            cin >> x;
            p[i][j] = (int)((lint)x * mod_pow(100, MOD - 2) % MOD);
        }

    for (int i = n; i <= 5; ++i) p[i][i] = 1;

    vector<int> tri;
    for (int m = 0; m < 64; ++m)
        if (__builtin_popcount(m) == 3)
            tri.push_back(m);

    vector<lint> f(1 << 20), g(1 << 20);

    for (int mask = 0; mask < (1 << 18); ++mask) {
        bool grid[6][6] = {};
        lint prod = 1;
        int idx = 0;

        for (int r = 0; r < 6; ++r)
            for (int c = 0; c <= 2; ++c) {
                if (mask >> idx & 1) {
                    grid[r][c] = true;
                    prod = prod * p[r][c] % MOD;
                } else {
                    prod = prod * ((1 - p[r][c] + MOD) % MOD) % MOD;
                }
                ++idx;
            }

        int comb_mask = 0;
        for (int i = 0; i < (int)tri.size(); ++i) {
            int combo = tri[i];
            int idxs[3];
            int cnt = 0;
            for (int k = 0; k < 6; ++k)
                if (combo >> k & 1) idxs[cnt++] = k;

            if ((grid[idxs[0]][0] && grid[idxs[1]][1] && grid[idxs[2]][2]) ||
                (grid[idxs[0]][0] && grid[idxs[2]][1] && grid[idxs[1]][2]) ||
                (grid[idxs[1]][0] && grid[idxs[0]][1] && grid[idxs[2]][2]) ||
                (grid[idxs[1]][0] && grid[idxs[2]][1] && grid[idxs[0]][2]) ||
                (grid[idxs[2]][0] && grid[idxs[0]][1] && grid[idxs[1]][2]) ||
                (grid[idxs[2]][0] && grid[idxs[1]][1] && grid[idxs[0]][2]))
                comb_mask |= 1 << i;
        }

        f[comb_mask] = (f[comb_mask] + prod) % MOD;
    }

    for (int mask = 0; mask < (1 << 18); ++mask) {
        bool grid[6][6] = {};
        lint prod = 1;
        int idx = 0;

        for (int r = 0; r < 6; ++r)
            for (int c = 3; c <= 5; ++c) {
                if (mask >> idx & 1) {
                    grid[r][c] = true;
                    prod = prod * p[r][c] % MOD;
                } else {
                    prod = prod * ((1 - p[r][c] + MOD) % MOD) % MOD;
                }
                ++idx;
            }

        int comb_mask = 0;
        for (int i = 0; i < (int)tri.size(); ++i) {
            int combo = tri[i];
            int comp = combo ^ 63;
            int idxs[3];
            int cnt = 0;
            for (int k = 0; k < 6; ++k)
                if (comp >> k & 1) idxs[cnt++] = k;

            if ((grid[idxs[0]][3] && grid[idxs[1]][4] && grid[idxs[2]][5]) ||
                (grid[idxs[0]][3] && grid[idxs[2]][4] && grid[idxs[1]][5]) ||
                (grid[idxs[1]][3] && grid[idxs[0]][4] && grid[idxs[2]][5]) ||
                (grid[idxs[1]][3] && grid[idxs[2]][4] && grid[idxs[0]][5]) ||
                (grid[idxs[2]][3] && grid[idxs[0]][4] && grid[idxs[1]][5]) ||
                (grid[idxs[2]][3] && grid[idxs[1]][4] && grid[idxs[0]][5]))
                comb_mask |= 1 << i;
        }

        g[comb_mask] = (g[comb_mask] + prod) % MOD;
    }

    for (int b = 0; b < 20; ++b)
        for (int m = (1 << 20) - 1; m >= 0; --m)
            if (m >> b & 1)
                g[m] = (g[m] + g[m ^ (1 << b)]) % MOD;

    lint ans = 0;
    for (int m = 0; m < (1 << 20); ++m)
        ans = (ans + f[m] * g[((1 << 20) - 1) ^ m]) % MOD;

    cout << (1 - ans + MOD) % MOD << '\n';
    return 0;
}
